export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const booking = await getBooking(id);

  const updatedStartsAt = input.startsAt !== undefined ? parseInstant(input.startsAt) : booking.startsAt;
  const updatedEndsAt = input.endsAt !== undefined ? parseInstant(input.endsAt) : booking.endsAt;
  const updatedRoomId = input.roomId !== undefined ? input.roomId : booking.roomId;

  if (
    input.startsAt !== undefined ||
    input.endsAt !== undefined ||
    input.roomId !== undefined ||
    input.userId !== undefined
  ) {
    validateBookingDomainRules(updatedStartsAt, updatedEndsAt);

    if (input.roomId !== undefined) {
      const roomExists = await roomRepository.findById(input.roomId);
      if (!roomExists) {
        throw notFound('Room');
      }
    }

    if (input.userId !== undefined) {
      const userExists = await userRepository.findById(input.userId);
      if (!userExists) {
        throw notFound('User');
      }
    }

    if (
      updatedRoomId !== booking.roomId ||
      updatedStartsAt.getTime() !== booking.startsAt.getTime() ||
      updatedEndsAt.getTime() !== booking.endsAt.getTime()
    ) {
      const conflict = await repository.findConflict(updatedRoomId, updatedStartsAt, updatedEndsAt);
      if (conflict && conflict.id !== id) {
        throw bookingConflict(conflict.id);
      }
    }
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId: input.roomId } : {}),
    ...(input.userId !== undefined ? { userId: input.userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt: updatedStartsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt: updatedEndsAt } : {}),
  });
}

